#include <vector>
using namespace std;

// 检查一个状态是否所有色块大小均为奇数
bool check(int state, int r, int c) {
    vector<vector<bool>> visited(r, vector<bool>(c, false));
    int dx[4] = {-1, 1, 0, 0};
    int dy[4] = {0, 0, -1, 1};

    for (int i = 0; i < r; i++) {
        for (int j = 0; j < c; j++) {
            if (visited[i][j]) continue;

            // 当前格子颜色：0 表示红色，1 表示蓝色
            int color = (state >> (i * c + j)) & 1;

            // BFS 搜索同色连通块
            queue<pair<int, int>> q;
            q.push({i, j});
            visited[i][j] = true;
            int size = 0;

            while (!q.empty()) {
                auto [x, y] = q.front();
                q.pop();
                size++;

                for (int k = 0; k < 4; k++) {
                    int nx = x + dx[k];
                    int ny = y + dy[k];

                    if (nx >= 0 && nx < r && ny >= 0 && ny < c && !visited[nx][ny]) {
                        int nextColor = (state >> (nx * c + ny)) & 1;
                        if (nextColor == color) {
                            visited[nx][ny] = true;
                            q.push({nx, ny});
                        }
                    }
                }
            }

            // 出现偶数大小的色块则方案不合法
            if (size % 2 == 0) {
                return false;
            }
        }
    }
    return true;
}

// 统计所有优美涂色方案的数量
int solve(int r, int c) {
    int total = r * c;
    int ans = 0;

    for (int state = 0; state < (1 << total); state++) {
        if (check(state, r, c)) {
            ans++;
        }
    }
    return ans;
}

int main() {
    int r, c;
    cin >> r >> c;
    cout << solve(r, c) << endl;
    return 0;
}
